    parts = [dict(item) for item in raw.get("parts", []) if isinstance(item, dict)]
    context_id = raw.get("contextId")
    return A2aUpdate(
        kind="message",
        message_id=str(raw.get("messageId") or ""),
        context_id=str(context_id) if context_id else None,
        parts=parts,
